# One row for every enumerated functional requirement in sections 2–14.
rows=[];sec=0;index=collections.Counter()
for line in src.splitlines():
 m=re.match(r'## (\d+)\.',line)
 if m:sec=int(m[1])
 m=re.match(r'^(?:- |\d+\. )(.*)',line)
 if m and 2<=sec<=14:
  index[sec]+=1;rows.append(dict(section=sec,n=index[sec],requirement=m[1],status='NOT TESTED',evidence='Առանձին ամբողջական փորձարկում չի կատարվել։',file=files.get(sec,''),problem='PASS չի հայտարարվում։'))
def mark(section,indices,status,evidence,problem='—'):
 for row in rows:
  if row['section']==section and row['n'] in indices:row.update(status=status,evidence=evidence,problem=problem)
